const SHARE_JS = `var LVS=[null,{a:"#34D399",b:"#059669",bg:"#ECFDF5",d1:"#0B3D2E",d2:"#14675A"},{a:"#38BDF8",b:"#2563EB",bg:"#EFF6FF",d1:"#0B2A5B",d2:"#1B4FB5"},{a:"#A78BFA",b:"#6D4AE0",bg:"#F5F3FF",d1:"#2A1763",d2:"#4C2FB0"},{a:"#FBBF24",b:"#EA580C",bg:"#FFF7ED",d1:"#5A2A06",d2:"#A04A12"}],LV=3;try{LV=+localStorage.getItem("gardenLv")||3}catch(e){}function applyLv(n){LV=n;var t=LVS[n],r=document.documentElement.style;r.setProperty("--a",t.a);r.setProperty("--b",t.b);r.setProperty("--cbg",t.bg);r.setProperty("--d1",t.d1);r.setProperty("--d2",t.d2);try{localStorage.setItem("gardenLv",n)}catch(e){}document.querySelectorAll(".lvbar button").forEach(function(b){var on=+b.dataset.l===n;b.classList.toggle("on",on);b.style.background=on?"linear-gradient(135deg,"+t.a+","+t.b+")":""})}document.querySelectorAll(".lvbar button").forEach(function(b){b.onclick=function(){applyLv(+b.dataset.l)}});applyLv(LV);var ov=document.getElementById("ov"),card=document.getElementById("card"),toastEl=document.getElementById("toast"),lastF=null;function toast(t){toastEl.textContent=t;toastEl.classList.add("on");clearTimeout(toast.t);toast.t=setTimeout(function(){toastEl.classList.remove("on")},2200)}function closeCard(){ov.classList.remove("on");if(lastF)lastF.focus()}function showCard(h,from){lastF=from||null;var i=h.indexOf("</h2>");card.innerHTML="<div class='chead'>"+h.slice(0,i+5)+"</div><div class='cbody'>"+h.slice(i+5)+"</div>";ov.classList.add("on");var c=card.querySelector("#cl");if(c){c.onclick=closeCard;c.focus()}}ov.addEventListener("click",function(e){if(e.target===ov)closeCard()});document.addEventListener("keydown",function(e){if(e.key==="Escape"&&ov.classList.contains("on"))closeCard()});
var MC=(function(){var el,av,nm,tx,bt,SS=window.speechSynthesis;
function build(){if(el)return;el=document.createElement("div");el.className="mchat";el.setAttribute("role","dialog");el.setAttribute("aria-label","Linh vật trò chuyện");el.innerHTML="<div class='mc-in'><div class='mc-av' id='mcav'></div><div class='mc-box'><button class='mc-x' type='button' aria-label='Đóng'>✕</button><div class='mc-name' id='mcnm'></div><div class='mc-txt' id='mctx' aria-live='polite'></div><div class='mc-btns' id='mcbt'></div></div></div>";document.body.appendChild(el);av=el.querySelector("#mcav");nm=el.querySelector("#mcnm");tx=el.querySelector("#mctx");bt=el.querySelector("#mcbt");el.querySelector(".mc-x").onclick=close}
/* ảnh linh vật: thử lần lượt các đường dẫn trong imgs (tranh bé vẽ trước, rồi tranh có sẵn), hết thì dùng biểu tượng */
function img(box,o){box.innerHTML="";var list=(o.imgs||[]).slice();function next(){var u=list.shift();if(!u){box.innerHTML="<span class='mc-em'>"+(o.emoji||"🙂")+"</span>";return}var im=new Image();im.alt="";im.onerror=next;im.onload=function(){box.innerHTML="";box.appendChild(im)};im.src=u}next()}
var WHO="def";function speak(t){if(window.Voice)Voice.say(t,WHO,"vi")}
function say(t,btns){build();tx.textContent=t;bt.innerHTML="";(btns||[]).forEach(function(b){var x=document.createElement("button");x.type="button";x.textContent=b[0];if(b[2])x.className=b[2];x.onclick=function(){b[1](x)};bt.appendChild(x)});el.classList.add("on")}
function open(o){build();WHO=o.who||"def";nm.textContent=o.name||"";img(av,o);say(o.text,o.btns);if(o.speak)speak(o.text)}
function close(){if(el)el.classList.remove("on");if(window.Voice)Voice.stop()}
return{open:open,say:say,close:close,speak:speak,img:img}})();
function shuffle(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=a[i];a[i]=a[j];a[j]=t}return a}
`;
