var cv=document.getElementById("dcv"),cx=cv.getContext("2d"),col=DC[0],er=false,dr=false,lx=0,ly=0;cx.fillStyle="#fff";cx.fillRect(0,0,640,480);cx.lineCap="round";cx.lineJoin="round";
